/**
 * E-way bills are generated by staff on the government portal (ewaybillgst.gov.in) and then recorded against the
 * invoice here, with the PDF they downloaded. Nothing in this app talks to the government.
 */

/** Goods moved in one consignment worth more than this normally need an e-way bill. */
export const EWAY_BILL_THRESHOLD_RUPEES = 50000;

export const EWAY_BILL_PORTAL_URL = 'https://ewaybillgst.gov.in/';
export const MAX_EWAY_BILLS_PER_INVOICE = 10;
export const EWAY_BILL_FILE_TYPES = ['application/pdf', 'image/jpeg', 'image/png', 'image/webp'];

/** An e-way bill number is 12 digits. Spaces and dashes people copy along with it are ignored. */
export function normalizeEwayBillNumber(raw: unknown): string | null {
  if (typeof raw !== 'string' && typeof raw !== 'number') return null;
  const digits = String(raw).replace(/[\s-]/g, '');
  return /^\d{12}$/.test(digits) ? digits : null;
}

/** MH12AB1234, "mh 12 ab 1234", BH-series and the like: upper case, no spaces, 6-12 letters or digits. */
export function normalizeVehicleNumber(raw: unknown): string | null {
  if (typeof raw !== 'string') return null;
  const v = raw.replace(/[\s-]/g, '').toUpperCase();
  return /^[A-Z0-9]{6,12}$/.test(v) && /[A-Z]/.test(v) && /\d/.test(v) ? v : null;
}

/** yyyy-mm-dd that is a real calendar date, or null. */
export function parseIsoDate(raw: unknown): string | null {
  if (typeof raw !== 'string') return null;
  const m = raw.trim().match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (!m) return null;
  const d = new Date(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])));
  return d.getUTCFullYear() === Number(m[1]) && d.getUTCMonth() === Number(m[2]) - 1 && d.getUTCDate() === Number(m[3]) ? m[0] : null;
}

/**
 * Does this invoice probably need an e-way bill? Goods worth more than Rs. 50,000 do; invoices that are only
 * services (HSN/SAC starting 99) do not. Advice only: the person decides, the portal is the authority.
 */
export function likelyNeedsEwayBill(grandTotalRupees: number, hsnCodes: string[]): boolean {
  if (!(grandTotalRupees > EWAY_BILL_THRESHOLD_RUPEES)) return false;
  return hsnCodes.some((h) => !h.startsWith('99'));
}
